// Responsive site photos generated by `npm run images` (scripts/optimize-images.mjs)
// from images/originals/. Use with the <Photo> component:
//
//   <Photo name="community-1" alt="…" sizes={SIZES.halfColumn} />
import manifest from "./photos/manifest.json";

const files = import.meta.glob("./photos/*.webp", {
  eager: true,
  query: "?url",
  import: "default",
});

const urlFor = (name, width) => files[`./photos/${name}-${width}.webp`];

/** name -> { src, srcSet, width, height } */
export const photos = Object.fromEntries(
  Object.entries(manifest).map(([name, { width, height, widths }]) => {
    const fallback = widths.find((w) => w >= 800) ?? widths.at(-1);
    return [
      name,
      {
        src: urlFor(name, fallback),
        srcSet: widths.map((w) => `${urlFor(name, w)} ${w}w`).join(", "),
        width,
        height,
      },
    ];
  })
);

/** `sizes` attribute values for the photos, matching the page CSS. */
export const SIZES = {
  // .col / .clergy / .intro / .timeline: 50% of the page up to 800px on
  // desktop, full width (max 600px) below 960px.
  halfColumn: "(max-width: 960px) min(100vw, 600px), min(50vw, 800px)",
  // Home "Mission" marquee: 3:2 images, 90% of a 35vh (min 200px) strip.
  marquee: "max(47vh, 270px)",
  // Home hero: most of the viewport width.
  hero: "(max-width: 960px) 100vw, 85vw",
};
